+      ? Platform.resolvedExecutable
+      : (_whichFa() ?? 'fa');
+  try {
+    final process = await (spawn ?? _startInherited)(exe, launchArgs);
+    await Future<void>.delayed(settleDelay);
+    final exitCode = await process.exitCode
+        .then<int?>((code) => code)
