}

/// The confirm/write step shared by the `project` and `global` scopes:
/// the surgical `compaction.engine` upsert, validated with the real
/// parser before the file is written.
Future<bool> _writeCompactionEngineYaml(
  CompactionEngine engine, {
  required bool projectScope,
}) => _upsertConfigYaml(
  const ['compaction', 'engine'],
  engine.value,
  projectScope: projectScope,
  validate: (node) =>
      CompactionEngine.fromSection(node, label: 'settings flow'),
);

/// The engine the next compaction pass will use (live override wins;
/// structured is the resolved default since #287/#295).
CompactionEngine _effectiveCompactionEngine() =>
    config.liveCompactionEngine ??
    config.compactionEngine ??
    CompactionEngine.structured;

/// The settings-hub row and `/settings` summary label for the engine.
String _compactionStatusLabel() => _effectiveCompactionEngine().value;

/// Settings → Auto update (issue #1377): one pick cycles the policy
/// notify → on → off and persists to the GLOBAL config file through the
/// surgical upsert, validated with the real parser before the write.
/// The notify default is never written — cycling back onto it drops the
/// key instead.
Future<void> startAutoUpdateFlow() async {
  final next = switch (config.autoUpdate) {
    AutoUpdateMode.notify => AutoUpdateMode.on,
    AutoUpdateMode.on => AutoUpdateMode.off,
    AutoUpdateMode.off => AutoUpdateMode.notify,
  };
  final wrote = next == AutoUpdateMode.notify
      ? await _dropAutoUpdateKey()
      : await _writeAutoUpdateYaml(next);
  if (wrote) config.autoUpdate = next;
}

/// The settings-hub row and `/settings` summary label for the policy.
String _autoUpdateStatusLabel() => config.autoUpdate.name;

