    case 'retriesPerEntry':
    case 'baseDelayMs':
    case 'maxBackoffMs':
    case 'maxWaitMs':
    case 'maxWaitForLastEntryMs':
    case 'keyBackoffMs':
      await _askRetryScalar(picked);
  }

