    'JctJXd6etpAaHg56YciFqzOa+/oyE4sgjunGqq0s4hx0ROHIhLC2almcekZFLEit\n'
    '[REDACTED:High Entropy String]\n'
    'P2gLH2uyw0KaQBQa1CQVCnUCAwEAAQ==\n'
