  io.writeln('dap agent name: ${snapshot.name ?? '(hostname default)'}');
  if (snapshot.connected ?? false) {
    io.writeln(
      'dap connection: connected as '
      '${snapshot.agentId ?? snapshot.name}',
    );
  } else {
    io.writeln('dap connection: not connected');
  }
}

