  try {
    await _repo.delete(
      await session.getMetadata(),
      actor: 'cli:empty-cleanup',
    );
    _session = null;
    // The session scope is gone — drop it from the resolution.
    unawaited(AgentCliTools(this).rebuildToolAvailability());
