+        throwsA(
+          isA<ConfigException>().having(
+            (e) => e.message,
+            'message',
+            autoUpdateError(1),
+          ),
+        ),
+      );
+      final map = loadYaml('auto_update: {a: 1}')['auto_update'];
+      expect(
+        () => autoUpdateModeFromYaml(map),
+        throwsA(
+          isA<ConfigException>().having(
+            (e) => e.message,
+            'message',
+            autoUpdateError(map),
+          ),
+        ),
+      );
+    });
+  });
